            unique_predicates.append(pred)

    # Check if we have any valid predicates
    if not unique_predicates:
        raise ValueError("No valid predicates are provided")

    # Get all items in the directory
    items = os.listdir(dir_path)

    # Create result dictionary
    result = {}

    for item in items:
        # Evaluate each predicate against the item name
        item_results = []
        for pred in unique_predicates:
            if callable(pred):
                # If predicate is a function, call it with the item name
                try:
                    item_results.append(pred(item))
                except Exception:
                    item_results.append(False)
            else:
                # If predicate is a string, treat it as a regex pattern
                try:
                    if re.search(pred, item):
                        item_results.append(True)
                    else:
                        item_results.append(False)
                except Exception:
                    item_results.append(False)
        result[item] = item_results

    return result
